#include <stdio.h>
int main(void) {
    int i, j, k = 0;
    for (i = 1; i <= 3; i++) {
        for (j = 1; j <= 3; j++) {
            if (j == 2) break;   /* 内层每圈只执行 j=1 这一次 */
            k++;
        }
    }
    printf("k=%d\n", k);
    return 0;
}

